suppressMessages({library(dplyr); library(tidyr); library(readr)})
w <- read_csv("data/raw/flows/rotorua_inflows_populated_withalum.csv", show_col_types = FALSE); n <- read_csv("data/raw/flows/rotorua_inflows_populated_noalum.csv", show_col_types = FALSE)
cat("rows", nrow(w), nrow(n), "| same columns:", identical(names(w), names(n)), "| streams:", paste(unique(w$Inflow), collapse = ","), "\n")
k <- c("Date", "InfNum"); J <- inner_join(w, n, by = k, suffix = c("_w", "_n")); cat("joined rows", nrow(J), "\n")
vars <- c("VOL", "TEMPTURE", "pH", "NH4", "NO3", "DRP", "DOPL", "POPL", "PIP", "TP", "TN", "TSS", "SSOL1", "SSOL2", "DOCL", "POCL")
d <- sapply(vars, \(v) { a <- J[[paste0(v, "_w")]]; b <- J[[paste0(v, "_n")]]; mean(abs(a - b) > 1e-9, na.rm = TRUE) }); cat("fraction of rows differing, by variable:\n"); print(round(d, 3))
J$Inflow <- J$Inflow_w; J$yr <- as.integer(format(J$Date, "%Y"))
diffs <- J |> group_by(Inflow) |> summarise(across(all_of(paste0(c("DRP", "PIP", "TP", "TSS"), "_w")), \(x) NA_real_), n = n()) 
S <- J |> filter(yr >= 2000) |> group_by(Inflow) |> summarise(n_diff_DRP = sum(abs(DRP_w - DRP_n) > 1e-9, na.rm = TRUE), n_diff_TP = sum(abs(TP_w - TP_n) > 1e-9, na.rm = TRUE), first_diff = suppressWarnings(min(Date[abs(DRP_w - DRP_n) > 1e-9])), last_diff = suppressWarnings(max(Date[abs(DRP_w - DRP_n) > 1e-9])), .groups = "drop"); print(as.data.frame(S))
cat("\nDosed streams: annual mean DRP and TP (g/m3), with vs no alum\n")
A <- J |> filter(Inflow %in% c("Utuhina", "Puarenga"), yr >= 2000, yr <= 2022) |> group_by(Inflow, yr) |> summarise(DRP_w = mean(DRP_w), DRP_n = mean(DRP_n), TP_w = mean(TP_w), TP_n = mean(TP_n), PIP_w = mean(PIP_w), PIP_n = mean(PIP_n), .groups = "drop") |> mutate(across(where(is.numeric) & !yr, \(x) round(x, 4)))
print(as.data.frame(A), row.names = FALSE)
cat("\nLoads 2011-2018 (kg P/yr; VOL assumed m3/d, conc g/m3):\n")
L <- J |> filter(Inflow %in% c("Utuhina", "Puarenga"), yr >= 2011, yr <= 2018) |> group_by(Inflow) |> summarise(across(c(DRP_w, DRP_n, TP_w, TP_n), \(x) sum(x * VOL_w, na.rm = TRUE) / 1000 / 8), .groups = "drop"); print(as.data.frame(L |> mutate(across(where(is.numeric), round))))
